/**
 * Save the referrer into a cookie
 *
 * @returns {void}
 */
pmw.bus.on("pmwLoad", () => {

	// If there is no referrer, then return
	if (!document.referrer) {
		return;
	}

	// If the referrer is already stored, then return
	if (pmw.retrieveData("referrer")) {
		return;
	}

	let referrerUrl      = new URL(document.referrer);
	let referrerHostname = referrerUrl.hostname;

	if (referrerHostname !== window.location.host) {
		pmw.storeData("referrer", referrerHostname);
	}
});

/**
 * The click IDs PMW harvests from landing page URLs: storage key => URL
 * parameter. Only Snap spells its parameter differently from the key.
 *
 * - gclid, wbraid, gbraid: Google Ads
 * - fbclid: Meta, https://developers.facebook.com/docs/marketing-api/conversions-api/parameters/fbp-and-fbc
 * - ttclid: TikTok
 * - scid (ScCid): Snapchat
 * - epik: Pinterest
 * - oppref: OpenAI (ChatGPT), https://developers.openai.com/ads/conversions-api
 * - ndclid: Nextdoor, https://developer.nextdoor.com/reference/conversion-user-matching
 * - msclkid: Microsoft, https://learn.microsoft.com/en-us/advertising/guides/uet-conversion-api-integration#click-id-msclkid
 * - rdt_cid: Reddit, https://business.reddithelp.com/s/article/manual-conversion-events-with-the-reddit-pixel
 * - aleid: AppLovin, https://support.applovin.com/en/growth/promoting-your-websites/api/axon-conversion-api
 */
pmw.clickIdUrlParameters = {
	gclid  : "gclid",
	wbraid : "wbraid",
	gbraid : "gbraid",
	fbclid : "fbclid",
	ttclid : "ttclid",
	scid   : "ScCid",
	epik   : "epik",
	oppref : "oppref",
	ndclid : "ndclid",
	msclkid: "msclkid",
	rdt_cid: "rdt_cid",
	aleid  : "aleid",
}

/**
 * Whether click IDs may be stored in this browser. A click ID is personal
 * data, and keeping it in sessionStorage is storage the ePrivacy rules tie to
 * consent. In Explicit Consent Mode nothing is stored before marketing
 * consent; in implicit mode the click ID is held until the visitor decides
 * (sending is gated on its own), and a visitor who denied marketing gets
 * nothing stored. Mirrors Click_Ids::is_collection_allowed() (DD-043).
 *
 * @returns {boolean}
 * @since 1.69.3
 */
pmw.isClickIdCollectionAllowed = () => {

	if (pmw.consent.categories.get().marketing === true) return true

	if (pmw.consent.explicitConsentModeActive()) return false

	return !pmw.visitorHasDecidedConsent()
}

/**
 * Whether the visitor has made a consent decision: on an earlier page
 * (visitorHasChosen) or on this one, through a CMP event or the consent API.
 *
 * @returns {boolean}
 * @since 1.69.3
 */
pmw.visitorHasDecidedConsent = () =>
	pmw.consent.settings.get().visitorHasChosen === true
	|| pmw.consent.decisionRecorded?.() === true

/**
 * Collects the click IDs from the URL into PMW's session storage.
 *
 * Only the platforms this shop has configured, where the server publishes
 * that list (Pro), and only while collection is allowed. Runs on load and
 * again when consent is granted, so a visitor who accepts on the landing
 * page still keeps the click IDs of that URL.
 *
 * @returns {void}
 * @since 1.69.3
 */
pmw.harvestClickIdsFromUrl = () => {

	if (!pmw.isClickIdCollectionAllowed()) return

	const activeKeys = pmwDataLayer?.general?.click_id_keys

	for (const [key, parameter] of Object.entries(pmw.clickIdUrlParameters)) {

		if (Array.isArray(activeKeys) && !activeKeys.includes(key)) continue

		let value = pmw.getUrlParameter(parameter)

		if (!value) continue

		if (key === "fbclid") {

			// The same click harvested again (consent granted later on the
			// same page) keeps its original creation time.
			const stored = pmw.retrieveData("fbclid")
			if (typeof stored === "string" && stored.endsWith("." + value)) continue

			// fbc format: fb.<subdomainIndex>.<creationTimeMs>.<fbclid>
			// The creation time must be in milliseconds (13 digits). Meta's fbevents.js
			// writes it that way, and PMW's isValidFbc / is_valid_fbc validators enforce
			// exactly 13 digits (\d{13}), so a seconds-based timestamp would be dropped.
			value = "fb.1." + Date.now() + "." + value
		}

		pmw.storeData(key, value)
	}
}

/**
 * Removes every click ID PMW stored in this browser: the session storage
 * copies and the first-party fallback cookie. The server removes its copy
 * when the next transfer reports the new consent state.
 *
 * @returns {void}
 * @since 1.69.3
 */
pmw.purgeClickIds = () => {

	for (const key of Object.keys(pmw.clickIdUrlParameters)) {
		if (pmw.retrieveData(key) !== undefined) pmw.deleteDataKey(key)
	}

	// A later grant must be able to send the same identifiers again.
	if (pmw.retrieveData("pmw_identifiers_sent") !== undefined) pmw.deleteDataKey("pmw_identifiers_sent")

	// _pmw_click_ids is the cookie's name before 1.69.3.
	for (const name of ["pmw_click_ids", "_pmw_click_ids"]) {
		if (pmw.getCookie(name)) pmw.deleteCookie(name)
	}
}

pmw.bus.on("pmwLoad", () => {
	pmw.harvestClickIdsFromUrl()
})

/**
 * A grant harvests the URL of the current page, a denial or withdrawal
 * purges what was stored. Registered before the Pro listener that transfers
 * the identifiers to the server, so that transfer already sees the result.
 */
document.addEventListener("pmw:consent:update", () => {

	if (pmw.isClickIdCollectionAllowed()) {
		pmw.harvestClickIdsFromUrl()
	} else {
		pmw.purgeClickIds()
	}
})

/**
 * Create our own load event in order to better handle script flow execution when JS "optimizers" shuffle the code.
 */
pmw.bus.on("pmwLoad", () => {
	// document.addEventListener("pmwLoad", function () {
	try {
		if (typeof pmwDataLayer != "undefined" && !pmwDataLayer?.pmw_loaded) {

			pmw.bus.emit("pmw:load-always");

			if (pmwDataLayer?.shop) {
				if (
					"product" === pmwDataLayer.shop.page_type &&
					"variable" !== pmwDataLayer.shop.product_type &&
					pmw.getMainProductIdFromProductPage()
				) {
					let product = pmw.getProductDataForViewItemEvent(pmw.getMainProductIdFromProductPage());
					pmw.bus.emit("pmw:view-item", product);
				} else if (
					"product" === pmwDataLayer.shop.page_type &&
					"variable" === pmwDataLayer.shop.product_type &&
					(
						!pmwDataLayer?.shop?.variations_output ||
						true === pmwDataLayer?.shop?.parent_view_item_on_variable_products
					) &&
					pmw.getMainProductIdFromProductPage()
				) {
					// Fire view_item with the parent product data. Either variations are not
					// reported separately at all, or the shop asked for the parent event
					// through the pmw_fire_parent_view_item_on_variable_products filter, in
					// which case the variation's own view_item still follows from
					// show_variation once the visitor picks one.
					let product = pmw.getProductDataForViewItemEvent(pmw.getMainProductIdFromProductPage());
					pmw.bus.emit("pmw:view-item", product);
				} else if ("product_category" === pmwDataLayer.shop.page_type) {
					pmw.bus.emit("pmw:view-category");
				} else if ("search" === pmwDataLayer.shop.page_type) {
					pmw.bus.emit("pmw:search");
				} else if ("cart" === pmwDataLayer.shop.page_type) {
					pmw.bus.emit("pmw:view-cart");
				} else if ("order_received_page" === pmwDataLayer.shop.page_type) {
					if (pmwDataLayer?.order && !pmw.isOrderIdStored(pmwDataLayer.order.id)) {
						pmw.bus.emit("pmw:purchase");
						pmw.writeOrderIdToStorage(pmwDataLayer.order.id, pmwDataLayer.order.key);
						if (typeof pmw.acrRemoveCookie === "function") pmw.acrRemoveCookie();
					}
				} else {
					pmw.bus.emit("pmw:everywhere-else");
				}
			} else {
				pmw.bus.emit("pmw:everywhere-else");
			}

			// Whether the visitor is signed in is general.user_logged_in, which
			// is is_user_logged_in() for this request. It is not user.id: on
			// the order confirmation page the user object is filled from the
			// order's customer on purpose, so that the purchase carries the
			// buyer's identifiers even on a payment webhook or a scheduled
			// run. Reading user.id as "signed in" made every guest checkout of
			// a registered customer emit a login on the confirmation page, for
			// a visitor who had never signed in, and every pixel listening to
			// pmw:pixel:login acted on it. user.id is still required because
			// the user object only exists on Pro, and a login event without
			// any identity has nothing to report.
			if (pmwDataLayer?.general?.user_logged_in && pmwDataLayer?.user?.id && !pmw.hasLoginEventFired()) {
				pmw.bus.emit("pmw:login");
				pmw.setLoginEventFired();
			}

			if (pmwDataLayer?.user?.account_just_created && !pmw.hasAccountCreatedEventFired()) {
				pmw.bus.emit("pmw:account-created");
				pmw.setAccountCreatedEventFired();
			}

			pmwDataLayer.pmw_loaded = true;
		}

	} catch (e) {
		console.error(e);
	}
});

/**
 * Register the show_variation event listener
 * in case lazy loading is enabled
 * because we have to register it immediately
 * and not after the onready event.
 */
if (pmwDataLayer?.general?.lazy_load_pmw) {
	pmw.registerShowVariationEventListener();
}

/**
 * In case lazy loading is enabled
 * we need to trigger the view-item event on
 * preselected variations.
 *
 * Check if a variation is selected on a variable product page
 * and trigger the view-item event if a variation is selected
 *
 * Fallback for the jQuery(".single_variation_wrap").on("show_variation", (event, variation) => {}) event listener
 * in case lazy loading is enabled and the event listener is not triggered.
 *
 * Only fires if variations_output is enabled, as the parent product view_item
 * is already triggered on page load when variations_output is disabled.
 */
pmw.bus.on("pmwLoad", () => {
	if (!pmwDataLayer?.general?.lazy_load_pmw) return;
	if (!pmwDataLayer?.shop?.variations_output) return;

	try {
		const $variationForm = jQuery(".variations_form");
		if (!$variationForm.length) return;

		const selectedValues = {};
		const allSelected    = $variationForm.find("select").toArray().every(select => {
			const value = jQuery(select).val();
			if (value) {
				selectedValues[jQuery(select).attr("name")] = value;
				return true;
			}
			return false;
		});

		if (!allSelected) return;

		const productVariations = $variationForm.data("product_variations");
		if (!productVariations) return;

		const matchingVariation = productVariations.find(variation =>
			Object.entries(selectedValues).every(([key, value]) =>
				variation.attributes[key] === value,
			),
		);

		if (matchingVariation) {
			pmw.triggerViewItemEventPrep(matchingVariation.variation_id);
		}
	} catch (e) {
		pmw.console.error(e);
	}
});

