/**
 * Add Contact Info
 *
 * The shopper has given an email address or phone number in the checkout
 * form. Pixels whose funnel events need an identity before an order exists
 * (Triple Whale) pick it up from here; everything else ignores it.
 *
 * All three sources (classic checkout fields, the Checkout block action and
 * the Interactivity API fallback) report on every change, so one identity is
 * one event: the email has to be complete and the pair must differ from the
 * last one reported.
 */
let lastContactKey = "";

pmw.bus.on("pmw:add-contact-info", (data = {}) => {

	const email = pmw.isEmail(data?.email) ? String(data.email).trim() : "";
	const phone = data?.phone ? String(data.phone).trim() : "";

	if (!email && !phone) return;

	const contactKey = email + "|" + phone;

	if (contactKey === lastContactKey) return;
	lastContactKey = contactKey;

	pmw.console.log("pmw:add-contact-info event fired", {data});

	/**
	 * Process the event through the unified event processor
	 */
	pmw.processEvent("add_contact_info", {...data, email, phone});
});

