/**
 * The product the last view_item on this page reported on, undefined until
 * the first one goes out.
 *
 * @type {string|null|undefined}
 */
let lastViewItemProductId;

/**
 * View Item event
 *
 * A variation that WooCommerce preselects is announced twice: once by the
 * page-load path that reads the selection off the variation form, and once
 * by WooCommerce's own show_variation event. Each pass produces its own
 * event ID, so the destination counts two product views for one page load.
 * The two are far enough apart in time when the product still has to be
 * fetched from the backend that the processor's own duplicate window cannot
 * be relied on, so the same product twice in a row is dropped here. Viewing
 * another variation and coming back still reports both views.
 */
pmw.bus.on("pmw:view-item", (product = null) => {

	pmw.console.log("pmw:view-item event fired", {product});

	const productId = product?.id ?? null;

	if (undefined !== lastViewItemProductId && productId === lastViewItemProductId) {
		pmw.console.log("Skipping view_item: this product was already reported on this page");
		return;
	}

	lastViewItemProductId = productId;

	/**
	 * Process the event through the unified event processor
	 */
	pmw.processEvent("view_item", {
		product: product,
	});
});

